package com.oms.messaging;
import com.oms.common.tenant.TenantRouting;
import com.ruoyi.common.core.tracing.Tracing;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import javax.annotation.Resource;
import java.util.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
@Service @ConditionalOnProperty(name="oms.messaging.enabled",havingValue="true") public class MessageOutbox {
 @Resource public JdbcTemplate db;@Resource PlatformTransactionManager transactionManager;
 @Value("${oms.messaging.service}") String service;
 @Value("${oms.tracing.ui-url:}") String tracingUiUrl="";
 public String service(){return service;}
 final ThreadLocal<String> retryParent=new ThreadLocal<>();
 public static String s(Map<String,?> row,String k){return row.get(k)==null?"":String.valueOf(row.get(k));}
 public static long n(Map<String,?> row,String k){try{return Long.parseLong(s(row,k));}catch(Exception e){return 0;}}
 public static void require(boolean b,String m){if(!b)throw new IllegalArgumentException(m);}
 public static String token(){return UUID.randomUUID().toString().replace("-","");}
 public static String hash(String s){try{byte[] b=MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8));StringBuilder r=new StringBuilder();for(byte v:b)r.append(String.format("%02x",v));return r.toString();}catch(Exception e){throw new IllegalStateException(e);}}
 public <T>T tx(java.util.function.Supplier<T> action){return new TransactionTemplate(transactionManager).execute(status->action.get());}
 /** Joins the caller's local database transaction. No broker I/O occurs here. */
 public String enqueue(String company,String type,long business,long version,String number,String key,long delay){String c=TenantRouting.company(company);require(business>0&&version>=0&&type.matches("[A-Z_]{1,40}")&&number!=null&&number.length()<=128&&delay>=0&&delay<=86400,"消息业务范围无效");return tx(()->{String event="ME"+token();db.update("INSERT IGNORE INTO oms_message_outbox(company_code,service_code,event_id,message_type,business_id,business_version,business_number,dedupe_key,trace_id,parent_event_id,source_trace_id,next_publish_at,next_process_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,DATE_ADD(NOW(3),INTERVAL ? SECOND),DATE_ADD(NOW(3),INTERVAL ? SECOND))",c,service,event,type,String.valueOf(business),version,number,hash(type+":"+key),"MT"+token(),retryParent.get()==null?"":retryParent.get(),Tracing.traceId(),delay,delay);return db.queryForObject("SELECT event_id FROM oms_message_outbox WHERE company_code=? AND service_code=? AND dedupe_key=?",String.class,c,service,hash(type+":"+key));});}
 public Map<String,Object> row(String c,String event){List<Map<String,Object>> r=db.queryForList("SELECT m.*,EXISTS(SELECT 1 FROM oms_message_outbox newer WHERE newer.company_code=m.company_code AND newer.service_code=m.service_code AND newer.message_type=m.message_type AND newer.business_id=m.business_id AND newer.id>m.id) has_newer FROM oms_message_outbox m WHERE company_code=? AND service_code=? AND event_id=?",c,service,event);require(r.size()==1,"消息不存在或不属于当前公司及服务");return r.get(0);}
 public void attempt(String c,String event,String stage,String result,String mode,String message,long ms,String actor){db.update("INSERT INTO oms_message_attempt(company_code,event_id,stage,result,mode,message,duration_ms,actor,sw_trace_id) VALUES (?,?,?,?,?,?,?,?,?)",c,event,stage,result,mode,message==null?"":message.substring(0,Math.min(message.length(),1000)),Math.max(0,ms),actor==null?"":actor,Tracing.traceId());}
 public Map<String,Object> envelope(Map<String,Object> r){Map<String,Object> e=new LinkedHashMap<>();for(String k:Arrays.asList("event_id","schema_version","message_type","company_code","business_id","business_version","trace_id","service_code","create_time"))e.put(k,k.equals("create_time")?String.valueOf(r.get(k)):r.get(k));return e;}
 public void validate(Map<String,Object> e,Map<String,Object> r){require(n(e,"schema_version")==1&&service.equals(s(e,"service_code")),"消息结构版本或服务不匹配");for(String k:Arrays.asList("company_code","event_id","message_type","business_id","business_version","trace_id"))require(s(e,k).equals(s(r,k)),"消息与已落库业务通知不一致");}
 public boolean claimWork(String c,String event,String lease,String mode){return db.update("UPDATE oms_message_outbox SET process_state='PROCESSING',work_token=?,work_until=DATE_ADD(NOW(3),INTERVAL 180 SECOND),execution_mode=?,consume_attempts=consume_attempts+1,last_consumed_at=NOW(3) WHERE company_code=? AND service_code=? AND event_id=? AND process_state IN ('PENDING','WAITING','PROCESSING') AND next_process_at<=NOW(3) AND (work_until IS NULL OR work_until<NOW(3))",lease,mode,c,service,event)==1;}
 public void finish(String c,String event,String lease,MessageHandler.Outcome out,String mode,long ms){tx(()->{boolean waiting=out.state.equals("WAITING");int changed=db.update("UPDATE oms_message_outbox SET process_state=?,last_error=?,problem_code=?,business_attempts=IF(?,0,business_attempts+?),next_process_at=DATE_ADD(NOW(3),INTERVAL ? SECOND),next_publish_at=DATE_ADD(NOW(3),INTERVAL ? SECOND),publish_state=IF(?, 'PENDING', IF(?='COMPENSATION' AND publish_state<>'PUBLISHED','SKIPPED','PUBLISHED')),publish_token=NULL,publish_until=NULL,work_token=NULL,work_until=NULL,completed_at=IF(?,NULL,NOW(3)) WHERE company_code=? AND service_code=? AND event_id=? AND work_token=?",out.state,out.message,out.problemCode,out.progress&&!out.preserveAttempts,waiting&&!out.progress?1:0,out.delaySeconds,out.delaySeconds,waiting,mode,waiting,c,service,event,lease);if(changed==1)attempt(c,event,"PROCESS",out.state,mode,out.message,ms,mode.equals("MQ")?"消息消费者":"数据库补偿");return null;});}
 public Map<String,Object> list(String c,String type,String publish,String state,String keyword,int page,int size){return list(c,type,publish,state,keyword,"","",page,size);}
 public Map<String,Object> list(String c,String type,String publish,String state,String keyword,String problem,String focus,int page,int size){require(page>0&&page<=100000&&size>0&&size<=100&&keyword.length()<=128,"消息查询范围无效");List<Object> a=new ArrayList<>(Arrays.asList(c,service));String w=" WHERE company_code=? AND service_code=?";if(!type.isEmpty()){require(type.matches("[A-Z_]{1,40}"),"消息类型无效");w+=" AND message_type=?";a.add(type);}if(!publish.isEmpty()){require(Arrays.asList("PENDING","SENDING","PUBLISHED","UNCERTAIN","SKIPPED").contains(publish),"投递状态无效");w+=" AND publish_state=?";a.add(publish);}if(!state.isEmpty()){require(Arrays.asList("PENDING","PROCESSING","WAITING","SUCCESS","FAILED").contains(state),"处理状态无效");w+=" AND process_state=?";a.add(state);}if(!problem.isEmpty()){require(MessageProblem.CODES.contains(problem),"异常分类无效");w+=" AND (CASE WHEN process_state='SUCCESS' THEN 'NONE' WHEN problem_code='NONE' AND last_publish_error<>'' THEN 'DELIVERY' ELSE problem_code END)=?";a.add(problem);}if(!focus.isEmpty()){require(Arrays.asList("OVERDUE","FAILED","PUBLISH","ACTIVE").contains(focus),"任务关注范围无效");if(focus.equals("ACTIVE"))w+=" AND process_state IN ('PENDING','WAITING','PROCESSING')";if(focus.equals("OVERDUE"))w+=" AND process_state IN ('PENDING','WAITING','PROCESSING') AND next_process_at<=NOW(3) AND (work_until IS NULL OR work_until<NOW(3))";if(focus.equals("FAILED"))w+=" AND process_state='FAILED'";if(focus.equals("PUBLISH"))w+=" AND process_state IN ('PENDING','WAITING','PROCESSING') AND publish_state IN ('PENDING','UNCERTAIN')";}if(!keyword.isEmpty()){w+=" AND (event_id=? OR business_id=? OR business_number=? OR trace_id=? OR source_trace_id=? OR EXISTS(SELECT 1 FROM oms_message_attempt a WHERE a.company_code=m.company_code AND a.event_id=m.event_id AND a.sw_trace_id=?))";for(int i=0;i<6;i++)a.add(keyword);}long total=db.queryForObject("SELECT COUNT(*) FROM oms_message_outbox m"+w,Long.class,a.toArray());a.add(size);a.add((page-1)*size);List<Map<String,Object>> rows=db.queryForList("SELECT m.*,EXISTS(SELECT 1 FROM oms_message_outbox newer WHERE newer.company_code=m.company_code AND newer.service_code=m.service_code AND newer.message_type=m.message_type AND newer.business_id=m.business_id AND newer.id>m.id) has_newer FROM oms_message_outbox m"+w+" ORDER BY id DESC LIMIT ? OFFSET ?",a.toArray());rows.forEach(r->{r.put("problem",MessageProblem.view(r));safe(r);});return new LinkedHashMap<String,Object>(){{put("rows",rows);put("total",total);}};}
 public Map<String,Object> detail(String c,String event){Map<String,Object> r=row(c,event);r.put("problem",MessageProblem.view(r));r.put("tracing_ui_url",tracingUiUrl);r.put("chain",chain(c,r));r.put("envelope",envelope(r));r.put("attempts",db.queryForList("SELECT stage,result,mode,message,duration_ms,actor,sw_trace_id,create_time FROM oms_message_attempt WHERE company_code=? AND event_id=? ORDER BY id DESC LIMIT 100",c,event));((List<Map<String,Object>>)r.get("attempts")).forEach(MessageOutbox::safe);return safe(r);}
 public List<Map<String,Object>> chain(String c,Map<String,Object> row){List<Map<String,Object>> rows=db.queryForList("SELECT event_id,parent_event_id,business_version,process_state,execution_mode,problem_code,last_error,create_time,completed_at FROM oms_message_outbox WHERE company_code=? AND service_code=? AND message_type=? AND business_id=? ORDER BY id DESC LIMIT 50",c,service,s(row,"message_type"),s(row,"business_id"));rows.forEach(MessageOutbox::safe);return rows;}
 static Map<String,Object> safe(Map<String,Object> r){r.remove("dedupe_key");r.remove("publish_token");r.remove("publish_until");r.remove("work_token");r.remove("work_until");r.replaceAll((k,v)->v instanceof java.sql.Timestamp?((java.sql.Timestamp)v).toLocalDateTime().toString().replace('T',' '):v instanceof java.time.temporal.TemporalAccessor?v.toString().replace('T',' '):v);return r;}
}
